\begin{aligned}
\Gamma^r{}_{rr}
&=\frac12g^{r\rho}
 (\partial_r g_{r\rho}+\partial_r g_{\rho r}-\partial_\rho g_{rr})\\
&=\frac12g^{rr}
 (\partial_r g_{rr}+\partial_r g_{rr}-\partial_r g_{rr})
+\frac12g^{r\theta}
 (\partial_r g_{r\theta}+\partial_r g_{\theta r}-\partial_\theta g_{rr})\\
&=\frac12(1)(0+0-0)+\frac12(0)(0+0-0)\\
&=0.
\end{aligned}
\tag{3.29}
